def parse_json(s):
    s = s.strip()
    if not (s.startswith('[') and s.endswith(']')):
        raise ValueError('array only')
    inner = s[1:-1].strip()
    if not inner:
        return []
    return [int(x.strip()) for x in inner.split(',')]

def demo():
    return parse_json('[1,2]')
